      "s.it.school":"Private school","s.it.support":"Tutoring center","s.it.lang":"Language center","s.it.training":"Training institute","s.it.nursery":"Nursery / preschool","s.it.higher":"Private higher education",
      "s.role.director":"Director","s.role.pedago":"Pedagogical lead","s.role.coord":"Coordinator","s.role.hr":"Human resources","s.role.owner":"Institution owner",
      "s.lvl.primary":"Primary","s.lvl.college":"Middle school","s.lvl.high":"High school","s.lvl.lang":"Languages","s.lvl.support":"Support","s.lvl.training":"Training",
      "s.need.now":"Immediate","s.need.month":"This month","s.need.year":"Start of school year","s.need.try":"Just trying the service",
      "s.work.full":"Full-time","s.work.part":"Part-time","s.work.hours":"Set hours","s.work.temp":"Temporary cover",
      "s.urgent.yes":"Yes, urgent","s.urgent.no":"No, not urgent","s.exp.any":"Doesn't matter","s.exp.1":"1 year or more","s.exp.3":"3 years or more","s.exp.5":"5 years or more","s.local.yes":"Yes, preferred","s.local.no":"Doesn't matter",
